class RadioGroupItem(CoreComponent):
    @classmethod
    def create(
        cls,
        *children: Any,
        name: str,
        value: str,
        **props: Any,
    ) -> rx.Component:
        custom_classes = props.pop("class_name", "")

        input_props = {"name": name, "value": value}
        for key in list(props.keys()):
            if key in ClassNames.KNOWN_INPUT_PROPS or key.startswith(
                ("on_", "data-", "aria-"),
            ):
                input_props[key] = props.pop(key)

        input_props["type"] = "radio"
        input_props["data-slot"] = "radio-group-item-input"
    ) -> Component:
        table_id = props.get("id") or f"data-table-{uuid.uuid4().hex[:8]}"
        props["id"] = table_id

        cls.set_class_name(ClassNames.ROOT, props)

        toolbar = (
            rx.el.div(
                TableSearch.create(for_table=table_id),
                class_name=ClassNames.TOOLBAR,
            )
            if searchable
            else None
        )

        pagination = (
            rx.el.div(
                rx.el.span("", **{"data-dt-info": "true"}),
                rx.el.div(
                    rx.el.button(
                        "Prev",
                        class_name=ClassNames.PAGE_BUTTON,
                        **{"data-dt-prev": "true"},
                    ),
                    rx.el.span("", class_name="px-2", **{"data-dt-page-label": "true"}),
                    rx.el.button(
                        "Next",
                        class_name=ClassNames.PAGE_BUTTON,
                        **{"data-dt-next": "true"},
                    ),
                    class_name="flex items-center gap-1",
                ),
                class_name=ClassNames.PAGINATION,
            )
            if paginate
            else None
        )

        table_props = {"class_name": ClassNames.TABLE}
        scroll_wrapper = rx.el.div(
            Table.create(*children, **table_props),
            class_name=ClassNames.SCROLL,
        )

        props["on_mount"] = rx.call_script(
            f"window.__dataTable.init({table_id!r}, {{pageSize: {page_size}}})",
    ) -> Component:
        cls.set_class_name(ClassNames.HEAD, props)
        if sort_key:
